  "claims": [
    {
      "id": "1",
      "type": "CONST",
      "text": "The function uses the constant 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'.",
      "asserted_values": ["4142434445464748494a4b4c4d4e4f505152535455565758595a6162636465666768696a6b6c6d6e6f707172737475767778797a303132333435363738392b2f"],
      "confidence": 1.0
    },
    {
      "id": "2",
      "type": "IO",
      "text": "Returns 0xFFFFFFFFFFFFFFFF when out_cap < len.",
      "asserted_values": ["FFFFFFFFFFFFFFFF"],
      "confidence": 1.0,
      "io": {
        "when": "out_cap < len",
        "returns": "FFFFFFFFFFFFFFFF"
      }
    },
    {
      "id": "3",
      "type": "IO",
      "text": "Returns len when len < 3.",
      "asserted_values": ["0000000000000003"],
      "confidence": 1.0,
      "io": {
        "when": "len < 3",
        "returns": "0000000000000003"
      }
    },
    {
      "id": "4",
      "type": "IO",
      "text": "Returns len when len == 1.",
      "asserted_values": ["0000000000000001"],
      "confidence": 1.0,
      "io": {
