        "returns": "0000000000000001"
      }
    },
    {
      "id": "5",
      "type": "IO",
      "text": "Returns len when len == 2.",
      "asserted_values": ["0000000000000002"],
      "confidence": 1.0,
      "io": {
        "when": "len == 2",
        "returns": "0000000000000002"
      }
    },
    {
      "id": "6",
      "type": "SIDE",
      "text": "Writes to out[0..<len].",
      "asserted_values": [],
      "confidence": 1.0
    },
    {
      "id": "7",
      "type": "CF",
      "text": "Loops over the input data in chunks of 3 bytes.",
      "asserted_values": [],
      "confidence": 1.0
    }
  ],
  "recovered_c": "uint64_t fn_07(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if ((len + 2) / 3 << 2 > out_cap) {\n    return VERA_ERR;\n  }\n\n  const char *base64_chars = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\";\n\n  size_t i = 0;\n  while (i < len) {\n    uint32_t chunk = 0;\n    if (i + 2 < len) {\n      chunk = ((uint32_t)in[i] << 16) | ((uint32_t)in[i + 1] << 8) | in[i + 2];\n    } else if (i + 1 < len) {\n      chunk = ((uint32_t)in[i] << 16) | ((uint32_t)in[i + 1] << 8);\n    } else {\n      chunk = (uint32_t)in[i] << 16;\n    }\n\n    out[i / 3 * 4] = base64_chars[(chunk >> 18) & 0x3F];\n    out[i / 3 * 4 + 1] = base64_chars[(chunk >> 12) & 0x3F];\n    if (i + 2 < len) {\n      out[i / 3 * 4 + 2] = base64_chars[(chunk >> 6) & 0x3F];\n      out[i / 3 * 4 + 3] = base64_chars[chunk & 0x3F];\n    } else if (i + 1 < len) {\n      out[i / 3 * 4 + 2] = base64_chars[(chunk >> 6) & 0x3F];\n      out[i / 3 * 4 + 3] = '=';\n    } else {\n      out[i / 3 * 4 + 2] = base64_chars[(chunk >> 6) & 0x3F];\n      out[i / 3 * 4 + 3] = '=';\n      out[i / 3 * 4 + 4] = '=';\n    }\n\n    i += 3;\n  }\n\n  return i;\n}"
}
